def get_user_input():
    """Get user input for deposit or withdrawal."""
    while True:
        user_input = input("Enter 'deposit' or 'withdrawal' to perform an action: ").lower()
        if user_input in ['deposit', 'withdrawal']:
            return user_input
        else:
            print("Invalid input. Please enter 'deposit' or 'withdrawal'.")

def get_amount():
    """Get user input for the amount to deposit or withdraw."""
    while True:
        try:
            amount = float(input("Enter the amount to deposit or withdraw: $"))
            return amount
        except ValueError:
            print("Invalid input. Please enter a valid amount.")

def simulate_banking_system():
    """Simulate a simple banking system with deposit and withdrawal actions."""
    balance = 0

    while True:
        user_action = get_user_input()

        if user_action == 'deposit':
            deposit_amount = get_amount()
            balance += deposit_amount
            print(f"Your balance is ${balance}.")

        elif user_action == 'withdrawal':
            withdrawal_amount = get_amount()
            if withdrawal_amount > balance:
                print("Insufficient funds. Current balance is $", balance)
            else:
                balance -= withdrawal_amount
                print(f"Withdrawal successful. Your balance is ${balance}.")

        else:
            print("Invalid action. Please enter 'deposit' or 'withdrawal'.")

if __name__ == "__main__":
    simulate_banking_system()
```

This program defines three functions: `get_user_input()`, `get_amount()`, and `simulate_banking_system()`. The `simulate_banking_system()` function handles the main logic of the program, including getting user input, validating the input, and updating the balance. The `if statements` in the function are used to handle the deposit and withdrawal actions.
